patch:
diff --git a/repro-no-lonely-if.js b/repro-no-lonely-if.js
new file mode 100644
index 0000000..35d1451
--- /dev/null
+++ b/repro-no-lonely-if.js
@@ -0,0 +1,46 @@
+"use strict";
+
+// Reproduction: no-lonely-if autofix changes semantics when the reported
+// `if` sits in an `else` block of an `if` that is itself the unbraced
+// consequent of an outer `if` that has its own `else`.
+
+const assert = require("node:assert");
+const eslintPath = process.argv[2] || "./lib/api";
+const { Linter } = require(eslintPath);
+console.log("eslint", Linter.version, "from", eslintPath, "\n");
+
+const linter = new Linter();
+const config = { rules: { "no-lonely-if": "error" } };
+
+const code = [
+    "if (true)",
+    "\tif (false) {}",
+    "\telse { if (false) {} }",
+    "else throw Error('This `else` should have been unreachable!');"
+].join("\n");
+
+const messages = linter.verify(code, config);
+const { output, fixed } = linter.verifyAndFix(code, config);
+
+console.log("--- input ---\n" + code);
+console.log("\n--- reported ---");
+for (const m of messages) console.log(`${m.line}:${m.column} ${m.ruleId}: ${m.message} (fix: ${m.fix ? JSON.stringify(m.fix) : "none"})`);
+console.log("\n--- fixed output (fixed=" + fixed + ") ---\n" + output);
+
+function run(src) {
+    try {
+        new Function(src)();
+        return "completed normally";
+    } catch (e) {
+        return "threw: " + e.message;
+    }
+}
+
+const before = run(code);
+const after = run(output);
+console.log("\n--- runtime ---");
+console.log("before fix:", before);
+console.log("after fix: ", after);
+
+assert.strictEqual(after, before, "BUG: no-lonely-if autofix changed program behavior");
+console.log("\nOK: autofix preserved behavior");
